const pools=new WeakMap();
export async function waitUntil142(test,label='recursos',timeout=60000){const start=performance.now();while(!test()){if(performance.now()-start>timeout)throw Error('No se terminó de preparar '+label+'. Reintenta la carga.');await new Promise(r=>setTimeout(r,40));}}
export async function prepareFrame142(view){if(!view?.renderer||!view.scene||!view.camera)throw Error('La vista 3D no está disponible');view.resize?.();view.scene.updateMatrixWorld(true);view.camera.updateMatrixWorld(true);if(view.renderer.compileAsync)await view.renderer.compileAsync(view.scene,view.camera);else view.renderer.compile?.(view.scene,view.camera);view.renderer.render(view.scene,view.camera);await new Promise(r=>requestAnimationFrame(r));}
function pool(host){if(pools.has(host))return pools.get(host);const cover=document.createElement('section');cover.className='load142';cover.hidden=true;cover.setAttribute('role','status');cover.setAttribute('aria-live','polite');cover.innerHTML='<div class="load142-card"><span class="load142-logo">M / LAB</span><small>PREPARANDO TU EXPERIENCIA</small><h2 data-load142-title></h2><div class="load142-track"><i></i></div><p data-load142-message>Descargando modelos, texturas y preparando la vista 3D…</p><div><button data-load142-retry hidden>Reintentar carga</button><button data-load142-exit>Volver al menú</button></div></div>';host.append(cover);const p={host,cover,jobs:new Set(),locked:new Map(),generation:0};pools.set(host,p);
 const unlock=()=>{for(const [n,value]of p.locked)n.inert=value;p.locked.clear();};p.unlock=()=>{unlock();if(host===document.body)document.body.dataset.loading142='false';};
 cover.querySelector('[data-load142-exit]').onclick=()=>{p.generation++;p.jobs.clear();cover.hidden=true;p.unlock();if(host.tagName==='DIALOG')host.close();else window.metroGame?.home();};
 host.addEventListener('close',()=>{if(host.tagName==='DIALOG'){p.generation++;p.jobs.clear();cover.hidden=true;p.unlock();}});
 document.addEventListener('keydown',e=>{if(cover.hidden||cover.contains?.(e.target)||host===document.body&&e.target?.closest?.('dialog[open]'))return;e.preventDefault();e.stopImmediatePropagation();},true);return p;
}
export async function gate142(title,task,{host=document.body}={}){
 const p=pool(host),generation=p.generation,job={title,failed:false};if(host===document.body)document.body.dataset.loading142='true';p.jobs.add(job);const show150=()=>{if(generation===p.generation&&p.jobs.has(job))p.cover.hidden=false;};const timer150=setTimeout(show150,180);p.cover.querySelector('[data-load142-title]').textContent=title;p.cover.querySelector('[data-load142-message]').textContent='Descargando modelos, texturas y preparando la vista 3D…';p.cover.querySelector('[data-load142-retry]').hidden=true;
 for(const n of host.children){if(n===p.cover||host===document.body&&n.tagName==='DIALOG')continue;if(!p.locked.has(n))p.locked.set(n,n.inert);n.inert=true;}
 try{const result=await task();clearTimeout(timer150);if(generation!==p.generation)return result;p.jobs.delete(job);if(!p.jobs.size){p.cover.hidden=true;p.unlock();}return result;}catch(error){clearTimeout(timer150);if(generation!==p.generation)return;job.failed=true;show150();p.cover.querySelector('[data-load142-message]').textContent=error?.message||'No se pudieron preparar los recursos.';const retry=p.cover.querySelector('[data-load142-retry]');retry.hidden=false;retry.onclick=()=>{for(const x of p.jobs)if(x.failed)p.jobs.delete(x);void gate142(title,task,{host});};console.error('Carga142',title,error);return undefined;}
}
